SOURCES=['wing','spiral','wave','triangle','moon','fan','hexagon','circle','arrow_merge','aperture','stars','cube','arrow_cross','globe','arrow_double_vertical']

def glyph(name):
    tree=ET.parse(SRC/f'{name}.svg')
    paths=[]
    for el in tree.getroot():
        if el.tag.endswith('path'):
            paths.append(f'<path d="{escape(el.attrib["d"])}"/>')
    return ''.join(paths)

def piece(name,x,y,w,h,color,rot=0,mirror=False,clip=None,opacity=1):
    sx=-w/16 if mirror else w/16
    ox=x+w if mirror else x
    trans=f'translate({ox} {y}) rotate({rot} {w/2} {h/2}) scale({sx} {h/16})'
    return f'<g transform="{trans}" fill="{color}" opacity="{opacity}"'+(f' clip-path="url(#{clip})"' if clip else '')+f'>{glyph(name)}</g>'

