def svg(body, extra=''):
    return f'''<svg xmlns="http://www.w3.org/2000/svg" width="128" height="128" viewBox="0 0 128 128"><defs><clipPath id="slit"><rect x="0" y="0" width="16" height="9"/></clipPath><clipPath id="half"><rect x="0" y="0" width="8" height="16"/></clipPath></defs>{extra}<g stroke-linejoin="round" stroke-linecap="round">{body}</g></svg>'''

